  ccxt::any parseDepositAddress(ccxt::any depositAddress,
                                ccxt::any currency = ccxt::any{}) override {
    //
    //     {
    //         "address": "1HdjGr6WCTcnmW1tNNsHX7fh4Jr5C2PeKe",
    //         "valid_until": 1620041926,
    //         "currency": "BTC",
    //         "label": "Savings"
    //     }
    //
    ccxt::any address =
        this->safeString(depositAddress, std::string("address"));
    ccxt::any currencyId =
        this->safeString(depositAddress, std::string("currency"));
    return ccxt::dict{
        {std::string("info"), depositAddress},
        {std::string("currency"), this->safeCurrencyCode(currencyId, currency)},
        {std::string("network"), ccxt::any{}},
        {std::string("address"), address},
        {std::string("tag"), ccxt::any{}},
    };
  }

  /**
   * @method
   * @name paymium#createOrder
   * @description create a trade order
   * @see
   * https://paymium.github.io/api-documentation/#tag/Order/operation/create-order
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type 'market' or 'limit'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much of currency you want to trade in units of
   * base currency
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  createOrder(ccxt::any symbol, ccxt::any type, ccxt::any side,
              ccxt::any amount, ccxt::any price = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("type"),
                      add(this->capitalize(type), std::string("Order"))},
                     {std::string("currency"),
                      ::getValue(market, std::string("id"))},
                     {std::string("direction"), side},
                     {std::string("amount"), amount},
                 };
                 if (isTrue(!isEqual(type, std::string("market")))) {
                   ::setValue(request, std::string("price"), price);
                 }
                 ccxt::any response = awaitValue(this->privatePostUserOrders(
                     this->extend(request, params)));
                 return this->safeOrder(
                     ccxt::dict{
                         {std::string("info"), response},
                         {std::string("id"),
                          this->safeString(response, std::string("uuid"))},
                     },
                     market);
               })
        .share();
  }

  /**
   * @method
   * @name paymium#cancelOrder
   * @description cancels an open order
   * @see
   * https://paymium.github.io/api-documentation/#tag/Order/operation/cancel-order
   * @param {string} id order id
   * @param {string} symbol not used by cancelOrder ()
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} An [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  cancelOrder(ccxt::any id, ccxt::any symbol = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        ccxt::any request = ccxt::dict{
                            {std::string("uuid"), id},
                        };
                        ccxt::any response =
                            awaitValue(this->privateDeleteUserOrdersUuidCancel(
                                this->extend(request, params)));
                        return this->safeOrder(ccxt::dict{
                            {std::string("info"), response},
                        });
                      })
        .share();
  }

  /**
   * @method
   * @name paymium#transfer
   * @description transfer currency internally between wallets on the same
   * account
   * @see
   * https://paymium.github.io/api-documentation/#tag/Transfer/operation/create-email-transfer
   * @param {string} code unified currency code
   * @param {float} amount amount to transfer
   * @param {string} fromAccount account to transfer from
   * @param {string} toAccount account to transfer to
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [transfer structure]{@link
   * https://docs.ccxt.com/?id=transfer-structure}
   */
  std::shared_future<ccxt::any>
  transfer(ccxt::any code, ccxt::any amount, ccxt::any fromAccount,
           ccxt::any toAccount, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any currency = this->currency(code);
                 if (isTrue(isLessThan(getIndexOf(toAccount, std::string("@")),
                                       0))) {
                   throw ExchangeError(toString(
                       add(this->id,
                           std::string(" transfer() only allows transfers to "
                                       "an email address"))));
                 }
                 if (isTrue(isTrue(!isEqual(code, std::string("BTC"))) &&
                            isTrue(!isEqual(code, std::string("EUR"))))) {
                   throw ExchangeError(toString(
                       add(this->id,
                           std::string(" transfer() only allows BTC or EUR"))));
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("currency"),
                      ::getValue(currency, std::string("id"))},
                     {std::string("amount"),
                      this->currencyToPrecision(code, amount)},
                     {std::string("email"), toAccount},
                 };
                 ccxt::any response =
                     awaitValue(this->privatePostUserEmailTransfers(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "uuid": "968f4580-e26c-4ad8-8bcd-874d23d55296",
                 //         "type": "Transfer",
                 //         "currency": "BTC",
                 //         "currency_amount": "string",
                 //         "created_at": "2013-10-24T10:34:37.000Z",
                 //         "updated_at": "2013-10-24T10:34:37.000Z",
                 //         "amount": "1.0",
                 //         "state": "executed",
                 //         "currency_fee": "0.0",
                 //         "btc_fee": "0.0",
                 //         "comment": "string",
                 //         "traded_btc": "string",
                 //         "traded_currency": "string",
                 //         "direction": "buy",
                 //         "price": "string",
                 //         "account_operations": [
                 //             {
                 //                 "uuid":
                 //                 "968f4580-e26c-4ad8-8bcd-874d23d55296",
                 //                 "amount": "1.0",
                 //                 "currency": "BTC",
                 //                 "created_at": "2013-10-24T10:34:37.000Z",
                 //                 "created_at_int": 1389094259,
                 //                 "name": "account_operation",
                 //                 "address":
                 //                 "1FPDBXNqSkZMsw1kSkkajcj8berxDQkUoc",
                 //                 "tx_hash": "string",
                 //                 "is_trading_account": true
                 //             }
                 //         ]
                 //     }
                 //
                 return this->parseTransfer(response, currency);
               })
        .share();
  }

  ccxt::any parseTransfer(ccxt::any transfer,
                          ccxt::any currency = ccxt::any{}) override {
    //
    //     {
    //         "uuid": "968f4580-e26c-4ad8-8bcd-874d23d55296",
    //         "type": "Transfer",
    //         "currency": "BTC",
    //         "currency_amount": "string",
    //         "created_at": "2013-10-24T10:34:37.000Z",
    //         "updated_at": "2013-10-24T10:34:37.000Z",
    //         "amount": "1.0",
    //         "state": "executed",
    //         "currency_fee": "0.0",
    //         "btc_fee": "0.0",
    //         "comment": "string",
    //         "traded_btc": "string",
    //         "traded_currency": "string",
    //         "direction": "buy",
    //         "price": "string",
    //         "account_operations": [
    //             {
    //                 "uuid": "968f4580-e26c-4ad8-8bcd-874d23d55296",
    //                 "amount": "1.0",
    //                 "currency": "BTC",
    //                 "created_at": "2013-10-24T10:34:37.000Z",
    //                 "created_at_int": 1389094259,
    //                 "name": "account_operation",
    //                 "address": "1FPDBXNqSkZMsw1kSkkajcj8berxDQkUoc",
    //                 "tx_hash": "string",
    //                 "is_trading_account": true
    //             }
    //         ]
    //     }
    //
    ccxt::any currencyId = this->safeString(transfer, std::string("currency"));
    ccxt::any updatedAt = this->safeString(transfer, std::string("updated_at"));
    ccxt::any timetstamp = this->parseDate(updatedAt);
    ccxt::any accountOperations =
        this->safeValue(transfer, std::string("account_operations"));
    ccxt::any firstOperation =
        this->safeValue(accountOperations, 0, ccxt::dict{});
    ccxt::any status = this->safeString(transfer, std::string("state"));
    return ccxt::dict{
        {std::string("info"), transfer},
        {std::string("id"), this->safeString(transfer, std::string("uuid"))},
        {std::string("timestamp"), timetstamp},
        {std::string("datetime"), this->iso8601(timetstamp)},
        {std::string("currency"), this->safeCurrencyCode(currencyId, currency)},
        {std::string("amount"),
         this->safeNumber(transfer, std::string("amount"))},
        {std::string("fromAccount"), ccxt::any{}},
        {std::string("toAccount"),
         this->safeString(firstOperation, std::string("address"))},
        {std::string("status"), this->parseTransferStatus(status)},
    };
  }

  virtual ccxt::any parseTransferStatus(ccxt::any status) {
    ccxt::any statuses = ccxt::dict{
        {std::string("executed"), std::string("ok")},
    };
    return this->safeString(statuses, status, status);
  }

  ccxt::any sign(ccxt::any path, ccxt::any api = std::string("public"),
                 ccxt::any method = std::string("GET"),
                 ccxt::any params = ccxt::dict{},
                 ccxt::any headers = ccxt::any{},
                 ccxt::any body = ccxt::any{}) override {
    ccxt::any url =
        add(add(add(add(::getValue(::getValue(this->urls, std::string("api")),
                                   std::string("rest")),
                        std::string("/")),
                    this->version),
                std::string("/")),
            this->implodeParams(path, params));
    ccxt::any query = this->omit(params, this->extractParams(path));
    if (isTrue(isEqual(api, std::string("public")))) {
      if (isTrue(isGreaterThan(getArrayLength(getObjectKeys(query)), 0))) {
        url = add(url, add(std::string("?"), this->urlencode(query)));
      }
    } else {
      this->checkRequiredCredentials();
      ccxt::any nonce = toString(this->nonce());
      ccxt::any auth = add(nonce, url);
      headers = ccxt::dict{
          {std::string("Api-Key"), this->apiKey},
          {std::string("Api-Nonce"), nonce},
      };
      if (isTrue(isEqual(method, std::string("POST")))) {
        if (isTrue(isGreaterThan(getArrayLength(getObjectKeys(query)), 0))) {
          body = this->json(query);
          auth = add(auth, body);
          ::setValue(headers, std::string("Content-Type"),
                     std::string("application/json"));
        }
      } else {
        if (isTrue(isGreaterThan(getArrayLength(getObjectKeys(query)), 0))) {
          ccxt::any queryString = this->urlencode(query);
          auth = add(auth, queryString);
          url = add(url, add(std::string("?"), queryString));
        }
      }
      ::setValue(
          headers, std::string("Api-Signature"),
          this->hmac(this->encode(auth), this->encode(this->secret), sha256));
    }
    return ccxt::dict{
        {std::string("url"), url},
        {std::string("method"), method},
        {std::string("body"), body},
        {std::string("headers"), headers},
    };
  }

  ccxt::any handleErrors(ccxt::any httpCode, ccxt::any reason, ccxt::any url,
                         ccxt::any method, ccxt::any headers, ccxt::any body,
                         ccxt::any response, ccxt::any requestHeaders,
                         ccxt::any requestBody) override {
    if (isTrue(isEqual(response, ccxt::any{}))) {
      return ccxt::any{};
    }
    ccxt::any errors = this->safeValue(response, std::string("errors"));
    if (isTrue(!isEqual(errors, ccxt::any{}))) {
      throw ExchangeError(
          toString(add(add(this->id, std::string(" ")), this->json(response))));
    }
    return ccxt::any{};
  }
